    const reversedStr = cleanedStr.split('').reverse().join('');
    ```
    *   `.split('')`: Converts the string into an array of individual characters.
    *   `.reverse()`: Reverses the order of elements in that array.

Here are a few ways to write a JavaScript function to return the $n$-th Fibonacci number, depending on the efficiency and the constraints you are aiming for.

### 1. Iterative Approach (Most Efficient for Standard Use)

This method uses a loop and is very efficient ($\mathcal{O}(n)$ time complexity and $\mathcal{O}(1)$ space complexity).

```javascript
/**
 * Calculates the n-th Fibonacci number using an iterative approach.
 * The sequence starts with F(0) = 0 and F(1) = 1.
 *
 * @param {number} n The index of the Fibonacci number to find (must be a non-negative integer).
 * @returns {number} The n-th Fibonacci number.
 * @throws {Error} If n is negative.
 */
function fibonacciIterative(n) {
    if (n < 0) {
        throw new Error("Input must be a non-negative integer.");
    }
    if (n === 0) {
        return 0;
    }
    if (n === 1) {
        return 1;
    }

    let a = 0;
    let b = 1;
    let result = 0;

    // Start loop from the 2nd number up to the n-th number
    for (let i = 2; i <= n; i++) {
        result = a + b;
        a = b;
        b = result;
    }

    return result;
}

// Example Usage:
console.log(`Fibonacci(0): ${fibonacciIterative(0)}`);   // Output: 0
console.log(`Fibonacci(1): ${fibonacciIterative(1)}`);   // Output: 1
console.log(`Fibonacci(6): ${fibonacciIterative(6)}`);   // Output: 8 (0, 1, 1, 2, 3, 5, 8)
console.log(`Fibonacci(10): ${fibonacciIterative(10)}`); // Output: 55
```

### 2. Recursive Approach (Simple but Inefficient)

This approach directly follows the mathematical definition ($F(n) = F(n-1) + F(n-2)$). However, it recalculates the same values many times, leading to exponential time complexity ($\mathcal{O}(2^n)$), which is very slow for large $n$.

```javascript
/**
 * Calculates the n-th Fibonacci number using a recursive approach.
 * WARNING: This is very inefficient for large values of n.
 *
 * @param {number} n The index of the Fibonacci number to find (must be a non-negative integer).
 * @returns {number} The n-th Fibonacci number.
 * @throws {Error} If n is negative.
 */
function fibonacciRecursive(n) {
    if (n < 0) {
        throw new Error("Input must be a non-negative integer.");
    }
    if (n === 0) {
        return 0;
    }
    if (n === 1) {
        return 1;
    }
    return fibonacciRecursive(n - 1) + fibonacciRecursive(n - 2);
}

