This implementation uses a closure to maintain the state of the last execution time and ensures that the function is only called at most once every specified time interval.

```javascript
/**
 * Creates a throttled version of a function that only invokes it at most once
 * per every wait milliseconds.
 *
 * @param {Function} func The function to throttle.
 * @param {number} wait The number of milliseconds to wait between invocations.
 * @returns {Function} A new function that throttles the original function.
 */
function throttle(func, wait) {
    let timeoutId = null;
    let lastArgs = null;
    let lastThis = null;
    let lastExecTime = 0;

    return function(...args) {
        const context = this;
        const now = Date.now();

        // Check if enough time has passed since the last execution
        if (now - lastExecTime >= wait) {
            // Execute immediately
            lastExecTime = now;
            func.apply(context, args);
        } else {
            // If called too soon, store the latest arguments and context
            // to be executed after the wait period is over.
            lastArgs = args;
            lastThis = context;

            // If there is no pending timeout, set one up.
            if (!timeoutId) {
                timeoutId = setTimeout(() => {
                    // Clear the timeout ID immediately after execution
                    timeoutId = null;
                    lastExecTime = Date.now();

                    // Execute the function with the last stored arguments
                    if (lastArgs) {
                        func.apply(lastThis, lastArgs);
                    }
                    // Reset stored arguments/context after execution
                    lastArgs = null;
                    lastThis = null;
                }, wait - (now - lastExecTime)); // Calculate remaining time for better accuracy
            }
        }
    };
}

